(async()=>{const a=await navigator.gpu.requestAdapter(),d=await a.requestDevice(),out={},buffer=()=>d.createBuffer({size:16,usage:GPUBufferUsage.MAP_READ|GPUBufferUsage.COPY_DST});d.pushErrorScope('validation');const b=buffer();const p=b.mapAsync(GPUMapMode.READ);out.pending=b.mapState;b.unmap();try{await p;out.abort='resolved'}catch(e){out.abort=e.name}out.afterAbort=b.mapState;await b.mapAsync(GPUMapMode.READ);const range=b.getMappedRange();b.destroy();out.destroy=[b.mapState,range.byteLength,b.size,b.usage];const src=d.createBuffer({size:16,usage:GPUBufferUsage.COPY_SRC|GPUBufferUsage.COPY_DST});d.queue.writeBuffer(src,0,new Uint32Array([8,9,10,11]));const dst=buffer(),e=d.createCommandEncoder();e.copyBufferToBuffer(src,0,dst,0,16);const c=e.finish();d.queue.submit([c]);await dst.mapAsync(GPUMapMode.READ);out.writeCopy=Array.from(new Uint32Array(dst.getMappedRange()));dst.unmap();d.queue.submit([c]);out.reused=Object.prototype.toString.call(await d.popErrorScope());d.pushErrorScope('validation');d.queue.writeBuffer(src,1,new Uint32Array([1]));out.writeAlignment=Object.prototype.toString.call(await d.popErrorScope());d.pushErrorScope('validation');try{const device2=await a.requestDevice();out.reuseAdapter='resolved';device2.destroy()}catch(e){out.reuseAdapter=e.name}out.scopeAfterReuse=await d.popErrorScope();d.destroy();return out})()
